contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 amount) public payable {
        require(asset != address(0));

        uint256 oracleAddrRaw = uint256(uint160(address(c.lrtConfig())));
        require(oracleAddrRaw != 0, "config not set");

        address oracleAddr = address(uint160(oracleAddrRaw));
        (bool okPrice, bytes memory priceData) = oracleAddr.staticcall(abi.encodeWithSignature("getAssetPrice(address)", asset));
        require(okPrice && priceData.length >= 32, "asset price read failed");
        uint256 assetPrice = abi.decode(priceData, (uint256));

        (bool okRseth, bytes memory rsethData) = oracleAddr.staticcall(abi.encodeWithSignature("getRSETHPrice()"));
        require(okRseth && rsethData.length >= 32, "rseth price read failed");
        uint256 rsethPrice = abi.decode(rsethData, (uint256));

        require(rsethPrice != 0, "rseth price is zero");

        uint256 result = c.getRsETHAmountToMint(asset, amount);

        uint256 expected = (amount * assetPrice) / rsethPrice;

        assert(result == expected);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 amount) public payable {
        require(asset != address(0));
        require(amount > 0);

        bool isSupported = c.isSupportedAsset(asset);
        require(isSupported);

        uint256 beforeTotal = c.getTotalAssetDeposits(asset);
        uint256 beforeBalance = address(c).balance;
        uint256 beforeSenderBalance = address(this).balance;

        bool reverted;
        try c.depositAsset(asset, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.getTotalAssetDeposits(asset);
        uint256 afterBalance = address(c).balance;
        uint256 afterSenderBalance = address(this).balance;

        if (reverted) {
            assert(afterTotal == beforeTotal);
        } else {
            assert(afterTotal >= beforeTotal);
        }

        assert(afterBalance >= beforeBalance);
        assert(afterSenderBalance <= beforeSenderBalance);
    }

    receive() external payable {}
}

