contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 amount) public payable {
        require(amount <= 1e30, "amount too large");

        address oracle = address(0);
        try c.lrtConfig() returns (address cfg) {
            ILRTConfig cfgInt = ILRTConfig(cfg);
            oracle = cfgInt.getContract(LRTConstants.LRT_ORACLE);
        } catch {}

        if (oracle == address(0)) {
            assert(true);
            return;
        }

        ILRTOracle oracleInt = ILRTOracle(oracle);
        uint256 assetPrice = oracleInt.getAssetPrice(asset);
        uint256 rsethPrice = oracleInt.getRSETHPrice();
        require(rsethPrice > 0, "rsethPrice is zero");

        uint256 mintAmount = c.getRsETHAmountToMint(asset, amount);

        assert(mintAmount == (amount * assetPrice) / rsethPrice);
    }

    receive() external payable {}
}

