        uint256 mintAmount = c.getRsETHAmountToMint(asset, amount);

        if (assetPrice == rsethPrice) {
            assert(mintAmount == amount);
        } else if (assetPrice < rsethPrice) {
            assert(mintAmount <= amount);
        } else {
            assert(mintAmount >= amount);
        }
    }

    receive() external payable {}
}

