            ILRTOracle lrtOracle = ILRTOracle(lrtOracleAddress);
            assetPrice = lrtOracle.getAssetPrice(asset);
            rsethPrice = lrtOracle.getRSETHPrice();
        } else {
            // unsupported asset leads to a revert from the public getter, whose mint amount can
            // still be computed off the configured oracle; use dummy values to avoid false rule
            assetPrice = 1;
            rsethPrice = 1;
        }

        uint256 expected = (amount * assetPrice) / rsethPrice;

        assert(rsethAmountToMint == expected || assetPrice == 1);
    }

    receive() external payable {}
