contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 depositAmount) public payable {
        // Record the amount of asset held by the test contract so depositAsset can transferFrom it.
        // Precondition: amount is positive so the zero-amount revert is not triggered.
        require(depositAmount > 0, "amount must be positive");
        require(asset != address(0), "asset must not be zero");

        // Ensure we have enough of the asset locally to approve the deposit pool.
        uint256 bal = IERC20(asset).balanceOf(address(this));
        require(bal >= depositAmount, "insufficient asset balance for test");

        // Read before-values through c's public surface.
        uint256 limitBefore = c.getAssetCurrentLimit(asset);
        uint256 totalBefore = c.getTotalAssetDeposits(asset);
        uint256 rsethToMint = c.getRsETHAmountToMint(asset, depositAmount);

        // Approve c to pull the asset (IERC20 interface is part of the external surface).
        IERC20(asset).approve(address(c), depositAmount);

        // Deciding call, top-level.
        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // If not reverted, contract state must be consistent with the general rule:
            // total deposits must have increased by exactly depositAmount, unless the
            // current limit was already insufficient (in which case a revert should have occurred).
            uint256 totalAfter = c.getTotalAssetDeposits(asset);
            assert(
                (limitBefore >= depositAmount && totalAfter == totalBefore + depositAmount)
                || (limitBefore < depositAmount)
            );
        } else {
            // If reverted, the revert must be explainable: either the current limit was
            // insufficient or the deposit amount was zero (but we ruled that out).
            assert(limitBefore < depositAmount);
        }
    }

    receive() external payable {}
}

