contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address asset, uint256 depositAmount) public payable {
        // No precondition needed: this rule holds for every supported asset and every amount
        // that reaches _mintRsETH. For an unsupported asset the call reverts before any mint,
        // so the equality below is vacuous for that branch (the deciding call reverts).

        // Snapshot the prices used by the formula before the state-changing call.
        address lrtOracleAddr = c.getContract(keccak256("LRT_ORACLE"));
        uint256 assetPrice = ILRTOracle(lrtOracleAddr).getAssetPrice(asset);
        uint256 rsethPrice = ILRTOracle(lrtOracleAddr).getRSETHPrice();

        // The contract's own view of the amount it will mint for this input.
        uint256 expectedMint = c.getRsETHAmountToMint(asset, depositAmount);

        // Make the deciding call; it may revert.
        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(expectedMint == (depositAmount * assetPrice) / rsethPrice);
        }
    }

    receive() external payable {}
}

