    constructor(C _c) { c = _c; }
    function run(address asset, address ndc1, address ndc2) public {
        require(asset != address(0), "zero asset");
        require(ndc1 != address(0), "zero delegator");
        require(ndc2 != address(0), "zero delegator");

        // Setup supported asset and node delegator queue through admin calls.
        // These calls are made as top-level statements, each may revert if preconditions fail.
        address[] memory ndcList = new address[](2);
        ndcList[0] = ndc1;
        ndcList[1] = ndc2;
        try c.addNodeDelegatorContractToQueue(ndcList) {} catch {}

        // Read the node delegator queue and compute the expected distribution independent of getAssetDistributionData.
        address[] memory queue = c.getNodeDelegatorQueue();
        uint256 ndcsCount = queue.length;
        uint256 assetLyingInNDCs = 0;
        uint256 assetStakedInEigenLayer = 0;
        for (uint256 i = 0; i < ndcsCount; i++) {
            assetLyingInNDCs += IERC20(asset).balanceOf(queue[i]);
            assetStakedInEigenLayer += INodeDelegator(queue[i]).getAssetBalance(asset);
        }
        uint256 assetLyingInDepositPool = IERC20(asset).balanceOf(address(c));

        (uint256 pool, uint256 ndcs, uint256 staked) = c.getAssetDistributionData(asset);
        uint256 total = c.getTotalAssetDeposits(asset);

        assert(total == pool + ndcs + staked && pool == assetLyingInDepositPool && ndcs == assetLyingInNDCs && staked == assetStakedInEigenLayer);
    }
    receive() external payable {}
}

