    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 depositAmount) public {
        require(depositAmount > 0, "deposit must be positive");
        require(c.lrtConfig().isSupportedAsset(asset), "unsupported asset");

        address rsethToken = c.lrtConfig().rsETH();
        uint256 rsethBalBefore = IERC20(rsethToken).balanceOf(address(this));
        uint256 expectedMint = c.getRsETHAmountToMint(asset, depositAmount);

        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 rsethBalAfter = IERC20(rsethToken).balanceOf(address(this));

        assert(!reverted && rsethBalAfter == rsethBalBefore + expectedMint);
    }
}

