contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 initialCount, address[] calldata nodes, uint256 overfillCount) public {
        require(initialCount > 0 && initialCount <= 10);
        require(nodes.length > 0);
        require(overfillCount > 10);

        // Initialize the contract with a dummy LRT config address (only for initializer gate).
        // The test contract itself is msg.sender; it is not a contract, so initializer condition passes on fresh deploy.
        c.initialize(address(0x1000));

        // Add initial valid node delegator contracts to the queue.
        address[] memory initialNodes = new address[](initialCount);
        for (uint256 i = 0; i < initialCount; i++) {
            initialNodes[i] = address(uint160(i + 1));
        }
        c.addNodeDelegatorContractToQueue(initialNodes);

        uint256 queueLenBefore = c.getNodeDelegatorQueue().length;

        // Try to add a batch of node delegators that would exceed maxNodeDelegatorCount.
        // This should revert and leave the queue unchanged.
        bool addReverted = false;
        try c.addNodeDelegatorContractToQueue(nodes) { 
            addReverted = false; 
        } catch { 
            addReverted = true; 
        }

        // If the add reverted, the queue length must be unchanged.
        // If it did not revert, the new queue length must be <= maxNodeDelegatorCount (10).
        // Since maxNodeDelegatorCount is 10 by default and we only added initialCount (<=10) plus nodes.length,
        // the call would only succeed if initialCount + nodes.length <= 10.
        uint256 queueLenAfter = c.getNodeDelegatorQueue().length;
        uint256 maxCount = c.maxNodeDelegatorCount();

        // The general rule: if the number of entries added would exceed maxCount, the call must revert and
        // queue length remains unchanged. If the call succeeds, queue length must not exceed maxCount and
        // must have increased by exactly nodes.length. The test chooses 'nodes' argument to ensure the
        // overfill case, but the rule is general for any 'nodes' array.
        bool wouldOverfill = queueLenBefore + nodes.length > maxCount;
        assert(
            (wouldOverfill && addReverted && queueLenAfter == queueLenBefore) ||
            (!wouldOverfill && !addReverted && queueLenAfter == queueLenBefore + nodes.length && queueLenAfter <= maxCount)
        );
    }

    receive() external payable {}
}
